这是个好问题。核心原因是：**这些设备的编号不是 udev 起的，是内核驱动自己分配的。**

## 编号从哪来

```c
// ttyS 驱动内部（简化）
for (i = 0; i < nr_uarts; i++) {
    // 内核自己决定叫 ttyS0, ttyS1, ttyS2 ...
    tty_register_device(tty_driver, i, NULL);  
}

// sd 磁盘驱动内部（简化）
// 内核扫描到第1个盘 → sda, 第2个 → sdb ...
// 分区 → sda1, sda2 ...
dev_set_name(&disk->part0, "sd%c", 'a' + index);
```

编号是**驱动代码里用循环/计数器**决定的，设备名叫 `/dev/ttyS%d` 还是 `/dev/ttyUSB%d` 都写死在驱动里。udev 只是**忠实地在 /dev 下创建同名节点**。

## 你的设备为什么不行

当你在模块里写：

```c
.name = "hello_dev",   // → /sys/class/misc/hello_dev
```

内核就**只认这一个名字**。它没有"编号"的概念——没有 `hello_dev0`、`hello_dev1`，因为你的代码里没写循环注册多个。

然后你用 udev 规则试图改名：

```
SUBSYSTEM=="misc", KERNEL=="hello_dev", NAME="hello1"
```

**`NAME` 指令对 misc 设备不生效**——这是 udev 的限制。`NAME` 主要用于 net（网卡）设备改名，块设备和字符设备的节点名由内核决定，udev 不能覆盖。

## 如果你想要编号效果

方法是：**在内核模块里注册多个设备，用编号命名。**

```c
#include <linux/module.h>
#include <linux/fs.h>
#include <linux/cdev.h>
#include <linux/device.h>

#define DEV_COUNT 4
#define DEV_NAME  "hello"

static dev_t         devno;
static struct cdev   hello_cdev;
static struct class  *hello_class;

static ssize_t hello_read(struct file *f, char __user *buf,
                          size_t len, loff_t *off)
{
    char msg[64];
    int n = snprintf(msg, sizeof(msg), "Hello from minor %d!\n",
                     iminor(f->f_inode));
    if (*off >= n) return 0;
    if (len > n - *off) len = n - *off;
    if (copy_to_user(buf, msg + *off, len)) return -EFAULT;
    *off += len;
    return len;
}

static const struct file_operations hello_fops = {
    .owner = THIS_MODULE,
    .read  = hello_read,
};

static int __init hello_init(void)
{
    int i;

    // 申请 4 个连续的次设备号
    alloc_chrdev_region(&devno, 0, DEV_COUNT, DEV_NAME);

    cdev_init(&hello_cdev, &hello_fops);
    cdev_add(&hello_cdev, devno, DEV_COUNT);

    // 创建 /sys/class/hello_class
    hello_class = class_create("hello_class");

    // 循环创建设备，内核自动发 uevent
    for (i = 0; i < DEV_COUNT; i++) {
        // → /sys/class/hello_class/hello0, hello1, hello2, hello3
        // → /dev/hello0, /dev/hello1, /dev/hello2, /dev/hello3
        device_create(hello_class, NULL, MKDEV(MAJOR(devno), i),
                      NULL, "%s%d", DEV_NAME, i);
    }
    return 0;
}

static void __exit hello_exit(void)
{
    int i;
    for (i = 0; i < DEV_COUNT; i++)
        device_destroy(hello_class, MKDEV(MAJOR(devno), i));
    class_destroy(hello_class);
    cdev_del(&hello_cdev);
    unregister_chrdev_region(devno, DEV_COUNT);
}

module_init(hello_init);
module_exit(hello_exit);
MODULE_LICENSE("GPL");
```

加载后你会看到：

```bash
$ ls -l /dev/hello*
crw-rw---- 1 root root 234, 0 ... /dev/hello0
crw-rw---- 1 root root 234, 1 ... /dev/hello1
crw-rw---- 1 root root 234, 2 ... /dev/hello2
crw-rw---- 1 root root 234, 3 ... /dev/hello3

$ cat /dev/hello0
Hello from minor 0!

$ cat /dev/hello2
Hello from minor 2!
```

## 对比总结

| 设备 | 编号谁决定的 | 在哪决定的 |
|------|------------|-----------|
| `/dev/ttyS0,1,2` | 串口驱动 | `for (i = 0; i < nr_uarts; i++)` 循环 |
| `/dev/sda, sdb` | 块设备驱动 | 按扫描顺序递增字母 |
| `/dev/input/event0,1` | input 子系统 | `input_register_device()` 递增 |
| **你的 misc 设备** | 你写的 `.name = "hello_dev"` | 只有一个名字，没有编号 |
| **改成 cdev 循环注册** | `device_create(..., "hello%d", i)` | 你自己的循环控制 |

**一句话：编号是驱动开发者用代码"写"出来的，不是某个框架自动给的。你想要 `/dev/hello1`，就在模块里 `device_create(..., "hello", 1)`。**
